#include <bits/stdc++.h>
using namespace std;static constexpr double TARGET=.70,C=.035;
struct S{bool ref=false,done=false;double rmid=0;int pos=0;double ep=0,emid=0,real=0,minliq=0,maxliq=-1e99;int rev=0;};
inline double op(const S&s,double b,double a){return s.pos==1?b-s.ep:s.pos==-1?s.ep-a:0;}inline double liq(const S&s,double b,double a){return s.pos?s.real+op(s,b,a)-C:s.real;}
bool parse(const string&l,int&date,int&sec,double&b,double&a){if(l.empty()||l[0]!='\"'||l.rfind("\"Exness\"",0)==0)return false;size_t c1=l.find(','),c2=l.find(',',c1+1),c3=l.find(',',c2+1),c4=l.find(',',c3+1);if(c4==string::npos)return false;string t=l.substr(c2+1,c3-c2-1);if(t.front()=='\"')t.erase(t.begin());if(!t.empty()&&t.back()=='\"')t.pop_back();date=stoi(t.substr(0,4))*10000+stoi(t.substr(5,2))*100+stoi(t.substr(8,2));sec=stoi(t.substr(11,2))*3600+stoi(t.substr(14,2))*60+stoi(t.substr(17,2));b=strtod(l.c_str()+c3+1,nullptr);a=strtod(l.c_str()+c4+1,nullptr);return b>0&&a>0;}
string tm(int s){char x[16];snprintf(x,sizeof(x),"%02d:%02d:%02d",s/3600,(s%3600)/60,s%60);return x;}
int main(int ac,char**av){if(ac<7){cerr<<"date startHour entry n1 d1 n2 d2\n";return 2;}int want=stoi(av[1]),start=stoi(av[2])*3600;double entry=stod(av[3]);int n1=stoi(av[4]);double d1=stod(av[5]);int n2=stoi(av[6]);double d2=stod(av[7]);ios::sync_with_stdio(false);cin.tie(nullptr);S s;string l;double lb=0,la=0;int ls=-1;cout<<"event,time,mid,bid,ask,pos,realized,liq,reversals,minliq\n";while(getline(cin,l)){int date,sec;double b,a;if(!parse(l,date,sec,b,a)||date!=want)continue;lb=b;la=a;ls=sec;if(sec<start)continue;double mid=(b+a)/2;if(!s.ref){s.ref=true;s.rmid=mid;cout<<"REF,"<<tm(sec)<<","<<mid<<","<<b<<","<<a<<",0,0,0,0,0\n";continue;}if(sec>=72000){if(s.pos)s.real+=op(s,b,a)-C;s.pos=0;s.minliq=min(s.minliq,s.real);cout<<"END20,"<<tm(sec)<<","<<mid<<","<<b<<","<<a<<",0,"<<s.real<<","<<s.real<<","<<s.rev<<","<<s.minliq<<"\n";return 0;}if(!s.pos){if(mid>=s.rmid+entry){s.pos=1;s.ep=a;s.emid=mid;s.real-=C;double q=liq(s,b,a);s.minliq=min(s.minliq,q);cout<<"ENTRY_BUY,"<<tm(sec)<<","<<mid<<","<<b<<","<<a<<",1,"<<s.real<<","<<q<<","<<s.rev<<","<<s.minliq<<"\n";}else if(mid<=s.rmid-entry){s.pos=-1;s.ep=b;s.emid=mid;s.real-=C;double q=liq(s,b,a);s.minliq=min(s.minliq,q);cout<<"ENTRY_SELL,"<<tm(sec)<<","<<mid<<","<<b<<","<<a<<",-1,"<<s.real<<","<<q<<","<<s.rev<<","<<s.minliq<<"\n";}continue;}double q=liq(s,b,a);s.minliq=min(s.minliq,q);s.maxliq=max(s.maxliq,q);if(q>=TARGET){s.real+=op(s,b,a)-C;cout<<"TARGET,"<<tm(sec)<<","<<mid<<","<<b<<","<<a<<",0,"<<s.real<<","<<s.real<<","<<s.rev<<","<<s.minliq<<"\n";return 0;}double rd=s.rev<n1?entry:(s.rev<n2?d1:d2);bool rv=(s.pos==1&&mid<=s.emid-rd)||(s.pos==-1&&mid>=s.emid+rd);if(rv){s.real+=op(s,b,a)-C;int old=s.pos;s.pos=-old;s.real-=C;s.ep=s.pos==1?a:b;s.emid=mid;s.rev++;double nq=liq(s,b,a);s.minliq=min(s.minliq,nq);cout<<"REV,"<<tm(sec)<<","<<mid<<","<<b<<","<<a<<","<<s.pos<<","<<s.real<<","<<nq<<","<<s.rev<<","<<s.minliq<<"\n";}}
 if(ls>=0){if(s.pos)s.real+=op(s,lb,la)-C;cout<<"LAST,"<<tm(ls)<<","<<(lb+la)/2<<","<<lb<<","<<la<<",0,"<<s.real<<","<<s.real<<","<<s.rev<<","<<s.minliq<<"\n";}}
